"""Deep semantic map of FMZ JavaScript strategy 画线类库Plot-library.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '画线类库Plot-library.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'label.', 'exchange.', 'Sleep(', 'GetTicker', 'GetRecords']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.', 'Uses ticker/depth data; OHLCV-only backtests cannot reproduce microstructure fills exactly.']
ORIGINAL_JAVASCRIPT = 'var chart = null\nvar series = []\nvar labelIdx = []\nvar preBarTime = 0\nvar preFlagTime = 0\nvar preDotTime = []\nvar hasPrimary = false;\n\nvar cfg = {\n    tooltip: {\n        xDateFormat: \'%Y-%m-%d %H:%M:%S, %A\'\n    },\n    legend: {\n        enabled: true,\n    },\n    plotOptions: {\n        candlestick: {\n            color: \'#d75442\',\n            upColor: \'#6ba583\'\n        }\n    },\n    rangeSelector: {\n        buttons: [{\n            type: \'hour\',\n            count: 1,\n            text: \'1h\'\n        }, {\n            type: \'hour\',\n            count: 3,\n            text: \'3h\'\n        }, {\n            type: \'hour\',\n            count: 8,\n            text: \'8h\'\n        }, {\n            type: \'all\',\n            text: \'All\'\n        }],\n        selected: 2,\n        inputEnabled: true\n    },\n    series: series,\n}\n\n$.GetCfg = function() {\n    return cfg\n}\n\n$.PlotHLine = function(value, label, color, style) {\n    if (typeof(cfg.yAxis) === \'undefined\') {\n        cfg.yAxis = {\n            plotLines: []\n        }\n    } else if (typeof(cfg.yAxis.plotLines) === \'undefined\') {\n        cfg.yAxis.plotLines = []\n    }\n    /*\n    Solid\n    ShortDash\n    ShortDot\n    ShortDashDot\n    ShortDashDotDot\n    Dot\n    Dash\n    LongDash\n    DashDot\n    LongDashDot\n    LongDashDotDot\n    */\n    var obj = {\n        value: value,\n        color: color || \'red\',\n        width: 2,\n        dashStyle: style || \'Solid\',\n        label: {\n            text: label || \'\',\n            align: \'center\'\n        },\n    }\n    var found = false\n    for (var i = 0; i < cfg.yAxis.plotLines.length; i++) {\n        if (cfg.yAxis.plotLines[i].label.text == label) {\n            cfg.yAxis.plotLines[i] = obj\n            found = true\n        }\n    }\n    if (!found) {\n        cfg.yAxis.plotLines.push(obj)\n    }\n    if (!chart) {\n        chart = Chart(cfg)\n    } else {\n        chart.update(cfg)\n    }\n}\n\n$.PlotRecords = function(records, title) {\n    var seriesIdx = labelIdx["candlestick"];\n    if (!chart) {\n        chart = Chart(cfg)\n        chart.reset()\n    }\n    if (typeof(seriesIdx) == \'undefined\') {\n        cfg.__isStock = true\n        seriesIdx = series.length\n        series.push({\n            type: \'candlestick\',\n            name: typeof(title) == \'undefined\' ? \'\' : title,\n            id: (hasPrimary ? \'records_\' + seriesIdx : \'primary\'),\n            data: []\n        });\n        chart.update(cfg)\n        labelIdx["candlestick"] = seriesIdx\n    }\n    hasPrimary = true;\n    if (typeof(records.Time) !== \'undefined\') {\n        var Bar = records;\n        if (Bar.Time == preBarTime) {\n            chart.add(seriesIdx, [Bar.Time, Bar.Open, Bar.High, Bar.Low, Bar.Close], -1)\n        } else if (Bar.Time > preBarTime) {\n            preBarTime = Bar.Time\n            chart.add(seriesIdx, [Bar.Time, Bar.Open, Bar.High, Bar.Low, Bar.Close])\n        }\n    } else {\n        for (var i = 0; i < records.length; i++) {\n            if (records[i].Time == preBarTime) {\n                chart.add(seriesIdx, [records[i].Time, records[i].Open, records[i].High, records[i].Low, records[i].Close], -1)\n            } else if (records[i].Time > preBarTime) {\n                preBarTime = records[i].Time\n                chart.add(seriesIdx, [records[i].Time, records[i].Open, records[i].High, records[i].Low, records[i].Close])\n            }\n        }\n    }\n    return chart\n}\n\n$.PlotLine = function(label, dot, time) {\n    if (!chart) {\n        cfg.xAxis = {\n            type: \'datetime\'\n        }\n        chart = Chart(cfg)\n        chart.reset()\n    }\n    var seriesIdx = labelIdx[label]\n    if (typeof(seriesIdx) === \'undefined\') {\n        seriesIdx = series.length\n        preDotTime[seriesIdx] = 0\n        labelIdx[label] = seriesIdx;\n        series.push({\n            type: \'line\',\n            id: (hasPrimary ? \'line_\' + seriesIdx : \'primary\'),\n            yAxis: 0,\n            showInLegend: true,\n            name: label,\n            data: [],\n            tooltip: {\n                valueDecimals: 5\n            }\n        })\n        hasPrimary = true;\n        chart.update(cfg)\n    }\n    if (typeof(time) == \'undefined\') {\n        time = new Date().getTime()\n    }\n\n    if (preDotTime[seriesIdx] != time) {\n        preDotTime[seriesIdx] = time\n        chart.add(seriesIdx, [time, dot])\n    } else {\n        chart.add(seriesIdx, [time, dot], -1)\n    }\n\n    return chart\n}\n\n\n$.PlotFlag = function(time, text, title, shape, color) {\n    if (!chart) {\n        chart = Chart(cfg)\n        chart.reset()\n    }\n    label = "flag";\n    var seriesIdx = labelIdx[label]\n    if (typeof(seriesIdx) === \'undefined\') {\n        seriesIdx = series.length\n        labelIdx[label] = seriesIdx;\n        series.push({\n            type: \'flags\',\n            onSeries: \'primary\',\n            data: []\n        })\n        chart.update(cfg)\n    }\n\n    var obj = {\n        x: time,\n        color: color,\n        shape: shape,\n        title: title,\n        text: text\n    }\n\n    if (preFlagTime != time) {\n        preFlagTime = time\n        chart.add(seriesIdx, obj)\n    } else {\n        chart.add(seriesIdx, obj, -1)\n    }\n\n    return chart\n}\n\n$.PlotTitle = function(title, chartTitle) {\n    cfg.subtitle = {\n        text: title\n    };\n    if (typeof(chartTitle) !== \'undefined\') {\n        cfg.title = {\n            text: chartTitle\n        };\n    }\n    if (chart) {\n        chart.update(cfg)\n    }\n}\n\nfunction main() {\n    var isFirst = true\n    while (true) {\n        var records = exchange.GetRecords();\n        if (records && records.length > 0) {\n            $.PlotRecords(records, \'BTC\')\n            if (isFirst) {\n                $.PlotFlag(records[records.length - 1].Time, \'Start\', \'S\')\n                isFirst = false\n                $.PlotHLine(records[records.length - 1].Close, \'Close\')\n            }\n        }\n        var ticker = exchange.GetTicker()\n        if (ticker) {\n            $.PlotLine(\'Last\', ticker.Last)\n            $.PlotTitle(\'Last \' + ticker.Last)\n        }\n\n        Sleep(60000)\n    }\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
